                    <div class="data-row"><span class="label">MEDICAÇÃO CONTÍNUA</span><span class="value">${a.saudeAcompanhamentos.medicacaoContinua||"-"} ${a.saudeAcompanhamentos.qualMedicacao?`(${a.saudeAcompanhamentos.qualMedicacao})`:""}</span></div>
